    "app/generated/page/page.tsx": "import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

const Calculator = () => {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('');

  const handleInputChange = (e) => {
    setInput(e.target.value);
  };

  const calculateResult = () => {
    try {
      // Evaluate the expression safely
      const evalResult = eval(input);
      setResult(evalResult);
    } catch (error) {
      setResult('Error');
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-screen bg-gray-100">
      <h1 className="text-2xl font-bold mb-4">Calculator</h1>
      <Input 
        type="text" 
        value={input} 
        onChange={handleInputChange} 
        placeholder="Enter expression" 
        className="mb-2"
      />
      <Button onClick={calculateResult} variant="outline">Calculate</Button>
      <div className="mt-4 text-xl">Result: {result}</div>
    </div>
  );
};

export default Calculator;
